CREATE TYPE "SupplierQualificationStatus" AS ENUM ('DRAFT','UNDER_REVIEW','APPROVED','ACTIVE','SUSPENDED','RETIRED');
CREATE TYPE "SupplierCapabilityStatus" AS ENUM ('UNDER_REVIEW','APPROVED','ACTIVE','SUSPENDED','REVOKED');
CREATE TYPE "PurchaseSourceStatus" AS ENUM ('DRAFT','ACTIVE','SUSPENDED','RETIRED');
CREATE TABLE purchase_source_type_definitions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, active BOOLEAN NOT NULL DEFAULT true, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE supplier_qualifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, supplier_partnership_id UUID NOT NULL UNIQUE REFERENCES company_partnerships(id) ON DELETE RESTRICT, status "SupplierQualificationStatus" NOT NULL DEFAULT 'DRAFT', qualification_notes TEXT, evidence_reference TEXT, effective_from DATE, effective_until DATE, approved_by UUID REFERENCES "User"(id), approved_at TIMESTAMPTZ, created_by UUID NOT NULL REFERENCES "User"(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE supplier_category_capabilities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, supplier_partnership_id UUID NOT NULL REFERENCES company_partnerships(id) ON DELETE RESTRICT, category_id UUID NOT NULL REFERENCES product_categories(id) ON DELETE RESTRICT, status "SupplierCapabilityStatus" NOT NULL DEFAULT 'UNDER_REVIEW', qualification_notes TEXT, effective_from DATE, effective_until DATE, approved_by UUID REFERENCES "User"(id), approved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(supplier_partnership_id,category_id));
CREATE TABLE purchase_sources (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), supplier_company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, supplier_partnership_id UUID NOT NULL REFERENCES company_partnerships(id) ON DELETE RESTRICT, source_code TEXT NOT NULL, source_type_id UUID NOT NULL REFERENCES purchase_source_type_definitions(id), branch_context TEXT, commercial_route TEXT, operational_context TEXT, status "PurchaseSourceStatus" NOT NULL DEFAULT 'DRAFT', internal_notes TEXT, created_by UUID NOT NULL REFERENCES "User"(id), approved_by UUID REFERENCES "User"(id), approved_at TIMESTAMPTZ, activated_at TIMESTAMPTZ, suspended_at TIMESTAMPTZ, retired_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(supplier_company_id,source_code));
CREATE TABLE purchase_source_contacts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), purchase_source_id UUID NOT NULL REFERENCES purchase_sources(id) ON DELETE RESTRICT, contact_type TEXT NOT NULL, display_name TEXT NOT NULL, email TEXT, phone TEXT, role_context TEXT, is_primary BOOLEAN NOT NULL DEFAULT false, active BOOLEAN NOT NULL DEFAULT true, created_by UUID NOT NULL REFERENCES "User"(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO purchase_source_type_definitions(code,name) VALUES ('MANUFACTURER_DIRECT','Manufacturer Direct'),('AUTHORIZED_DISTRIBUTOR','Authorized Distributor'),('DISTRIBUTOR','Distributor'),('WHOLESALER','Wholesaler'),('AGENT','Agent'),('DEALER','Dealer'),('CONTRACTOR','Contractor'),('OTHER','Other') ON CONFLICT DO NOTHING;
GRANT SELECT,INSERT,UPDATE ON purchase_source_type_definitions,supplier_qualifications,supplier_category_capabilities,purchase_sources,purchase_source_contacts TO sco_runtime;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['purchase_source_type_definitions','supplier_qualifications','supplier_category_capabilities','purchase_sources','purchase_source_contacts'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY %I_internal ON %I FOR ALL TO sco_runtime USING (current_setting(''app.sco_internal'',true)=''true'') WITH CHECK (current_setting(''app.sco_internal'',true)=''true'')',t,t); END LOOP; END $$;
